$('#floorSwitcher').addEventListener('click',floorClick);$('#floorsPanel').addEventListener('click',floorClick);$('#floorsPanel').addEventListener('change',e=>{const id=e.target.dataset.floorLabel;if(!id)return;const label=e.target.value.trim(),floor=state.floors.find(f=>f.id===id);if(!floor)return;if(!label||label.length>80){toast('Enter a floor label from 1 to 80 characters.');renderFloors();return}checkpoint();floor.label=label;save();});
function showPage(next){endDrag();page=next;$('#editorPage').hidden=page!=='editor';$('#overviewPage').hidden=page!=='overview';$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-selected',String(b.dataset.page===page))});if(page==='overview')renderOverview();else requestAnimationFrame(()=>render());}
function renderOverview(){const doc=pack(state);if(overviewScope!=='all'&&!doc.floors.some(f=>f.id===overviewScope))overviewScope='all';const data=report(doc,overviewScope),t=data.total;$('#overviewScope').innerHTML='<option value="all">All floors</option>'+doc.floors.map(f=>`<option value="${esc(f.id)}" ${overviewScope===f.id?'selected':''}>${esc(f.label)}</option>`).join('');$('#overviewScope').value=overviewScope;$$('[data-overview]').forEach(b=>{b.classList.toggle('active',b.dataset.overview===overviewTab);b.setAttribute('aria-selected',String(b.dataset.overview===overviewTab))});const warning=t.overlap?'<div class="reportWarning">Some sections overlap. Rack totals are nominal allocations by section and may double-count physical space. Resolve section overlaps in Editor before using whitespace figures for planning.</div>':'';let html=warning;
if(overviewTab==='dashboard'){if(!data.floors.some(f=>f.id===overviewFloor))overviewFloor=data.floors.find(f=>f.id===state.activeFloorId)?.id||data.floors[0]?.id;const f=data.floors.find(f=>f.id===overviewFloor),metric=(label,value,unit,note)=>`<article class="metric"><span>${label}</span><div>${value}<small>${unit}</small></div><p>${note}</p></article>`;html+=`<div class="metrics">${metric('Total floor capacity',fmt(t.footprint),'m²',data.floors.length+' floors in scope')}${metric('Whitespace',fmt(t.whitespace),'m²',percent(t.whitespace,t.footprint)+' of total floor area')}${metric('Unassigned rack capacity',fmt(t.unassignedPallets),'positions',fmt(t.unassigned)+' m² of unassigned racks')}${metric('Installed pallet capacity',fmt(t.pallets),'positions',t.racks+' racks · '+t.sections+' sections')}</div><div class="dashboardGrid"><article class="layoutCard"><div class="reportCardHeading"><div><span class="overline">CAPACITY MAP</span><h2>${esc(f?.label||'Layout')}</h2></div><div class="chartFloorTabs">${data.floors.map((q,i)=>`<button data-chart-floor="${esc(q.id)}" class="${q.id===f?.id?'active':''}" title="${esc(q.label)}">${doc.floors.findIndex(a=>a.id===q.id)+1}</button>`).join('')}</div></div><div class="capacityLegend"><span><i class="assignedSwatch"></i>Assigned racks</span><span><i class="blankSwatch"></i>Unassigned / unracked</span><span><i class="foundationSwatch"></i>Unsectioned floor</span><span><i class="reservedSwatch"></i>Reserved non-storage</span></div>${f?layoutChart(f):'<p class="empty">No floors yet.</p>'}<p class="chartCaption">To-scale footprint · rack divisions show proportional area, not physical rack placement. Hover a section for its breakdown.</p></article><article class="capacityBreakdown"><div class="reportCardHeading"><div><span class="overline">FLOOR BREAKDOWN</span><h2>${esc(f?.label||'')}</h2></div></div>${f?`${statRow('Foundation footprint',fmt(f.footprint)+' m²')}${statRow('Reserved non-storage',fmt(f.reserved)+' m²')}${statRow('Unsectioned space',fmt(f.unsectioned)+' m²')}${statRow('Assigned rack area',fmt(f.assigned)+' m²')}${statRow('Unassigned rack area',fmt(f.unassigned)+' m²')}${statRow('Unracked within sections',fmt(f.sections.reduce((n,s)=>n+s.stats.free,0))+' m²')}<div class="sectionKey">${f.sections.map((s,i)=>`<button class="sectionKeyRow" data-breakdown-section="${esc(s.id)}"><b>${i+1}</b><span>${esc(s.name)}<small>${fmt(s.stats.total)} m² · ${s.rackPlacement===false?'Reserved non-storage':s.stats.count+' racks · '+percent(s.stats.used,s.stats.total)+' racked'}</small></span></button>`).join('')||'<p class="empty">No sections on this floor.</p>'}</div>`:''}</article></div><article class="reportCard"><div class="reportCardHeading"><div><span class="overline">PLANNING OPPORTUNITIES</span><h2>Capacity by floor</h2></div></div>${table(['Floor','Floor area (m²)','Whitespace (m²)','Unsectioned (m²)','Unassigned positions','Assigned positions','Reserved m²'],data.floors.map(f=>[f.label,f.footprint,f.whitespace,f.unsectioned,f.unassignedPallets,f.assignedPallets,f.reserved]))}</article>`;
}else if(overviewTab==='tables'){html+=data.floors.map(f=>`<article class="reportCard"><div class="reportCardHeading"><div><span class="overline">FLOOR ${doc.floors.findIndex(q=>q.id===f.id)+1}</span><h2>${esc(f.label)}</h2></div><span>${fmt(f.footprint)} m² footprint</span></div>${table(['Floor area m²','Section area m²','Unsectioned m²','Rack area m²','Whitespace m²','Pallet positions'],[[f.footprint,f.sectionArea,f.unsectioned,f.used,f.whitespace,f.pallets]])}<h3 class="tableSubheading">Sections</h3>${table(['Section','Rack placement','Reserved m²','Area m²','Assigned rack m²','Unassigned rack m²','Unracked m²','Racks','Pallet positions'],f.sections.map(s=>[s.name,s.rackPlacement===false?'Disabled':'Enabled',s.stats.reserved,s.stats.total,s.stats.assigned,s.stats.unassigned,s.stats.free,s.stats.count,s.stats.pallets]))}<h3 class="tableSubheading">Racks by type and assignment</h3>${table(['Rack type','Section','Assigned racks','Unassigned racks','Floor area m²','Pallet positions'],doc.rackTypes.flatMap(type=>f.sections.flatMap(s=>{const racks=f.racks.filter(r=>r.typeId===type.id&&r.sectionId===s.id);return racks.length?[[type.name,s.name,racks.filter(r=>r.assigned).length,racks.filter(r=>!r.assigned).length,racks.length*type.length*type.width,racks.length*type.pallets]]:[]})))}</article>`).join('');html+=`<article class="reportCard"><div class="reportCardHeading"><h2>Rack type library</h2></div>${table(['Rack type','Length m','Width m','Height m','Footprint m²','Pallet positions'],doc.rackTypes.map(t=>[t.name,t.length,t.width,t.height,t.length*t.width,t.pallets]))}</article>`;
}else{const tabs=sheets(doc,overviewScope);excelSheet=Math.min(excelSheet,tabs.length-1);const s=tabs[excelSheet];html+=`<div class="excelWorkbook"><div class="excelToolbar"><span>▦ &nbsp; ${esc(s.name)}</span><span>${s.rows.length} records · ${s.headers.length} columns · Read-only</span></div><div class="sheetScroll"><table class="excelGrid"><thead><tr><th></th>${s.headers.map((_,i)=>`<th>${columnName(i)}</th>`).join('')}</tr></thead><tbody><tr class="sheetHeaders"><th>1</th>${s.headers.map(h=>`<td>${esc(h)}</td>`).join('')}</tr>${s.rows.map((r,i)=>`<tr><th>${i+2}</th>${r.map(v=>`<td class="${typeof v==='number'?'numeric':''}">${esc(v)}</td>`).join('')}</tr>`).join('')}${Array.from({length:Math.max(0,12-s.rows.length)},(_,i)=>`<tr><th>${s.rows.length+i+2}</th>${s.headers.map(()=>'<td></td>').join('')}</tr>`).join('')}</tbody></table></div><div class="sheetTabs">${tabs.map((s,i)=>`<button data-sheet="${i}" class="${i===excelSheet?'active':''}">${s.name}</button>`).join('')}</div></div>`;}$('#overviewContent').innerHTML=html+`<p class="reportFootnote">Whitespace = foundation floor area − installed rack footprint − reserved non-storage area. Includes unsectioned and storage-enabled unracked space; excludes unassigned rack footprint and reserved sections. Pallet positions are rack design capacity, not inventory counts. Aisles, obstructions and operating clearances are not reserved.</p>`;}
$$('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$$('[data-overview]').forEach(b=>b.onclick=()=>{overviewTab=b.dataset.overview;renderOverview()});$('#overviewScope').onchange=e=>{overviewScope=e.target.value;renderOverview()};$('#overviewContent').onclick=e=>{const floor=e.target.closest('[data-chart-floor]'),sheet=e.target.closest('[data-sheet]');if(floor){overviewFloor=floor.dataset.chartFloor;renderOverview()}if(sheet){excelSheet=Number(sheet.dataset.sheet);renderOverview()}};$('#downloadExcel').onclick=()=>{const blob=workbook(sheets(pack(state),overviewScope)),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(state.name.replace(/[^a-z0-9]/gi,'-')||'WSMS')+'-capacity.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Excel workbook downloaded');};
function highlightCapacitySection(id){$$('[data-capacity-section]').forEach(el=>el.classList.toggle('isHighlighted',el.dataset.capacitySection===id));$$('[data-breakdown-section]').forEach(el=>el.classList.toggle('isHighlighted',el.dataset.breakdownSection===id));}
function capacitySectionId(target){const el=target?.closest?.('[data-breakdown-section], [data-capacity-section]');return el?.dataset.breakdownSection||el?.dataset.capacitySection||null;}
$('#overviewContent').addEventListener('pointerover',e=>highlightCapacitySection(capacitySectionId(e.target)));
$('#overviewContent').addEventListener('pointerout',e=>highlightCapacitySection(capacitySectionId(e.relatedTarget)));
$('#overviewContent').addEventListener('focusin',e=>highlightCapacitySection(capacitySectionId(e.target)));
$('#overviewContent').addEventListener('focusout',e=>highlightCapacitySection(capacitySectionId(e.relatedTarget)));
